</span></span><span style="display:flex;"><span> <span style="color:#58a1dd">&#34;owner&#34;</span>: {
</span></span><span style="display:flex;"><span> <span style="color:#58a1dd">&#34;name&#34;</span>: <span style="color:#a6be9d">&#34;other&#34;</span>
